// This file is not generated by Speakeasy — it lets flags added in hand-written
// code appear in --usage. The schemas in schema.go are rendered from the API
// spec, so a flag such as create-suite's --wait is otherwise missing from them.

package usage

import (
	"fmt"
	"regexp"
	"strings"
)

var (
	usageCmdLine   = regexp.MustCompile(`^(\s*)cmd "([^"]+)".*\{$`)
	usageCloseLine = regexp.MustCompile(`^(\s*)\}$`)
)

// UsageFlag is a flag line for a --usage schema.
type UsageFlag struct {
	// Name and placeholder as the schema shows them, e.g. "--max-wait <duration>".
	Spec string
	Help string
}

// AddFlags adds flags to the schema of the command at path (e.g.
// "test run create-suite") and to every parent schema that nests it, so
// 'vf --usage' shows them as well as 'vf test run create-suite --usage'.
// Adding a flag the schema already has does nothing.
func AddFlags(path string, flags ...UsageFlag) {
	parts := strings.Fields(path)
	for key, schema := range usageSchemas {
		keyParts := strings.Fields(key)
		if len(keyParts) > len(parts) || strings.Join(parts[:len(keyParts)], " ") != key {
			continue
		}
		// A command's own schema starts with its own cmd line; the root's
		// starts with its children's.
		nested := parts
		if len(keyParts) > 0 {
			nested = parts[len(keyParts)-1:]
		}
		usageSchemas[key] = addFlagsToSchema(schema, nested, flags)
	}
}

func addFlagsToSchema(schema string, path []string, flags []UsageFlag) string {
	lines := strings.Split(schema, "\n")
	out := make([]string, 0, len(lines)+len(flags))
	var stack []usageCmd
	for _, line := range lines {
		if m := usageCmdLine.FindStringSubmatch(line); m != nil {
			stack = append(stack, usageCmd{indent: m[1], name: m[2]})
		} else if m := usageCloseLine.FindStringSubmatch(line); m != nil && len(stack) > 0 && stack[len(stack)-1].indent == m[1] {
			if stackMatches(stack, path) {
				for _, flag := range flags {
					flagLine := fmt.Sprintf("%s  flag %q help=%q", m[1], flag.Spec, flag.Help)
					if !strings.Contains(schema, flagLine) {
						out = append(out, flagLine)
					}
				}
			}
			stack = stack[:len(stack)-1]
		}
		out = append(out, line)
	}
	return strings.Join(out, "\n")
}

type usageCmd struct {
	indent string
	name   string
}

func stackMatches(stack []usageCmd, path []string) bool {
	if len(stack) != len(path) {
		return false
	}
	for i, entry := range stack {
		if entry.name != path[i] {
			return false
		}
	}
	return true
}
